import React, { useState } from 'react';
import Login from './screens/Login';
import Dashboard from './screens/Dashboard';
import NewPurchase from './screens/NewPurchase';
import Sales from './screens/Sales';
import Payment from './screens/Payment';
import './styles/theme.css';

export default function App() {
  const [currentScreen, setCurrentScreen] = useState('login'); // login, dashboard, purchase, sales, payment

  return (
    <div className="app-container">
      {/* Navigation Bar for Demo Testing */}
      {currentScreen !== 'login' && (
        <nav style={{ background: '#1B4D3E', padding: '10px 20px', display: 'flex', gap: '15px' }}>
          <button onClick={() => setCurrentScreen('dashboard')} style={navBtnStyle}>Dashboard</button>
          <button onClick={() => setCurrentScreen('purchase')} style={navBtnStyle}>New Purchase</button>
          <button onClick={() => setCurrentScreen('sales')} style={navBtnStyle}>New Sale</button>
          <button onClick={() => setCurrentScreen('payment')} style={navBtnStyle}>Payment Entry</button>
          <button onClick={() => setCurrentScreen('login')} style={{...navBtnStyle, background: '#E74C3C'}}>Logout</button>
        </nav>
      )}

      {/* Screen Router */}
      {currentScreen === 'login' && <Login onLoginSuccess={() => setCurrentScreen('dashboard')} />}
      {currentScreen === 'dashboard' && <Dashboard />}
      {currentScreen === 'purchase' && <NewPurchase />}
      {currentScreen === 'sales' && <Sales />}
      {currentScreen === 'payment' && <Payment />}
    </div>
  );
}

const navBtnStyle = {
  background: '#ffffff',
  color: '#1B4D3E',
  border: 'none',
  padding: '8px 15px',
  borderRadius: '4px',
  fontWeight: 'bold',
  cursor: 'pointer'
};
